    "explanation": "1. CONCEPT:\nCondition for geometrical isomerism in alkenes.\n\n2. GIVEN:\nAlkenes with restricted rotation about C=C.\n\n3. FORMULA / PRINCIPLE:\nEach doubly bonded carbon must hold two different groups: Ca(b)=Cc(d).\n\n4. STEP-BY-STEP SOLUTION:\n1. In but-2-ene, both C-2 and C-3 carry -H and -CH3 groups (two different groups on each carbon).\n2. Therefore, cis-but-2-ene (both -CH3 on same side) and trans-but-2-ene (opposite sides) exist.\n3. In propene, but-1-ene, and 2-methylpropene, one of the sp2 carbons carries two identical groups (two -H atoms), preventing cis-trans isomerism.\n\n5. FINAL ANSWER:\nOption A: But-2-ene (CH3-CH=CH-CH3)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nWhenever an sp2 carbon holds two identical atoms, geometrical isomerism is geometrically impossible.",
