      "concept": "Counting sigma and pi bonds in acyclic enynes.",
      "given": "Structure: HC#C-CH=CH-CH3.",
      "formula": "Single bond = 1 sigma; double bond = 1 sigma + 1 pi; triple bond = 1 sigma + 2 pi.",
      "stepByStep": "1. Draw out all bonds: H-C#C-C(H)=C(H)-C(H3).\n2. Sigma bonds: 1 (C-H) + 1 (C#C) + 1 (C-C) + 1 (C-H) + 1 (C=C) + 1 (C-H) + 1 (C-C) + 3 (C-H on CH3) = 10 sigma bonds.\n3. Pi bonds: 2 in triple bond + 1 in double bond = 3 pi bonds.\n4. Total: 10 sigma and 3 pi bonds.",
